  1094	 *   A=待应用角度  N=有 pending 没脏区  B=子矩形回退（本版没有）
  1095	 *   T=跟车余量用完/角度不一致  E=帧末  S=开航向朝上  L=路名开关 */
  1096	static void vmap_rot_why(char c)
  1097	{
  1098	    syslog(LOG_DEBUG, "[vrot] why %c\n", c);
  1099	}
  1100	
  1101	/**
  1102	 * @brief 用 EPIC 把整幅画布按当前 rot10 重新烘进 R。
  1103	 *
  1104	 * @details 一次约 138 ms（R 288×264，EPIC 任意角 ~0.55 Mpx/s），所以只在**角度变了 /
  1105	 *          余量用完 / 整帧结束**时调用；平地跟车只移动 R 的对象。
  1106	 */
  1107	static bool vmap_rot_full(vmap_view_t * view)
  1108	{
  1109	    int32_t pivot_x;
  1110	    int32_t pivot_y;
  1111	
  1112	    if (view == NULL || !view->heading_up || view->rbuf == NULL
  1113	        || view->cbuf == NULL || view->rcanvas == NULL) {
  1114	        return false;
  1115	    }
  1116	
  1117	    /* 切换窗口里 C 还在重铺：此时烘 R 会把半成品/旧标签带上屏。 */
  1118	    if (view->heading_switch_pending) {
  1119	        return false;
  1120	    }
  1121	
  1122	    /*
  1123	     * ⚠ 帧在飞时**绝不能烘**：`vmap_rot_full` 会被 GNSS 定时器经
  1124	     * `apply_canvas_pos → vmap_rot_track` 调到，而那时正北画布只画了一半瓦片、
  1125	     * 标签收集器也只填了一部分 ⇒ 烘出来是"半成品"，下一帧再纠正，观感就是
  1126	     * 地图卡住 + 文字乱跳（2026-10-28 现场）。等 `render_finish` 里再烘。
  1127	     */
  1128	    if (view->pump_phase != 0u) {
  1129	        return false;
  1130	    }
  1131	
  1132	    /*
  1133	     * 失败后的重试限频放在**这里**，而不是只放在 service 里：跟车余量、开关切换、
  1134	     * 帧末都直接调本函数，否则一次失败会在同一拍里被下一个入口再次触发。
  1135	     * 只限"失败重试"，正常重烘（帧末/余量/角度）不受这条窗口影响。
  1136	     */
  1137	    if (view->rot_fail_valid
  1138	        && (uint32_t)(lv_tick_get() - view->last_fail_ms) < VMAP_ROT_BAKE_MIN_MS) {
  1139	        return false;
  1140	    }
  1141	
  1142	    /* 骑手在画布里的位置 = 画布中心 + 跟车 pan。 */
  1143	    pivot_x = view->margin + view->view_w / 2 + (int32_t)lround(view->pan_dx);
  1144	    pivot_y = view->margin + view->view_h / 2 + (int32_t)lround(view->pan_dy);
  1145	    if (pivot_x < 0 || pivot_y < 0 || pivot_x >= view->w || pivot_y >= view->h) {
  1146	        pivot_x = view->w / 2;
  1147	        pivot_y = view->h / 2;
  1148	    }
  1149	
  1150	    if (!myvendor_epic_rotate(view->cbuf, view->stride, view->w, view->h,
  1151	            view->rbuf, view->rstride, view->rw, view->rh, view->rot10,
  1152	            pivot_x, pivot_y, view->rw / 2, view->rh / 2)) {
  1153	        /*
  1154	         * 失败分两种：参数/硬件不可用（R 没动），或 **EPIC 超时**（R 可能已被写了
  1155	         * 一部分，上一帧不能再信）。两种情况都按"R 是脏的"处理 —— 这里的记账是
  1156	         * 全树唯一的收口点，调用方（service / 跟车 / 帧末 / 开关切换）都不必各自判断：
  1157	         *   ① `rot_pending`：service 每拍重试整幅，直到成功；
  1158	         *   ② `last_fail_ms`：失败重试限频（入口处），避免同一拍被别的入口再打一次。
  1159	         *
  1160	         * ⚠ 已知边界：R 是单缓冲、EPIC 直写，超时后**无法回滚**上一帧。
  1161	         *   失败到下一次成功重烘之间，屏上可能是新旧混合的一帧；这段时间里
  1162	         *   `rot_broken` 会**冻结跟车平移**（否则按旧 r_pan 继续挪会把新旧两种基准
  1163	         *   叠在一起，错位越滚越大）。重试间隔 ≥1200 ms，连续失败可更久。
  1164	         *   要彻底消除得双缓冲（多 152 KB PSRAM），未做。
  1165	         */
  1166	        view->rot_pending = true;
  1167	        view->rot_fail_valid = true;
  1168	        view->rot_broken = true;
  1169	        view->last_fail_ms = lv_tick_get();
  1170	        return false;
  1171	    }
  1172	
  1173	    view->r_pan_x = view->pan_dx;
  1174	    view->r_pan_y = view->pan_dy;
  1175	    view->r_rot10 = view->rot10;
  1176	    view->rot_pending = false;
  1177	    view->rot_fail_valid = false;
  1178	    view->rot_broken = false;
  1179	    /* 余量重烘/帧末重烘/增量重烘都计入同一个限频窗口。 */
  1180	    view->last_bake_ms = lv_tick_get();
  1181	    vmap_rot_place(view, 0, 0);
  1182	    vmap_rot_labels_update(view, pivot_x, pivot_y);
  1183	    lv_obj_invalidate(view->rcanvas);
  1184	    return true;
  1185	}
  1186	
  1187	/**
  1188	 * @brief 把"帧外增量还没进 R"的记账补烘掉（限频窗口内先留着）。
  1189	 *
  1190	 * @details 由 200 ms 的航向拍调用（`vmap_view_set_heading`），所以即使某次增量
  1191	 *          之后再没有任何失效，内容也会在窗口到期后的下一拍上屏；不会永远停在旧版本。
  1192	 */
  1193	static void vmap_rot_service(vmap_view_t * view)
  1194	{
  1195	    bool angle;
  1196	
  1197	    if (view == NULL || !view->heading_up) {
  1198	        return;
  1199	    }
  1200	
  1201	    if (view->rcanvas != NULL
  1202	        && lv_obj_has_flag(view->rcanvas, LV_OBJ_FLAG_HIDDEN)) {
  1203	        /* R 还没接替（切换窗口或烘焙失败回退）：屏上是 C，先保住 C 的刷新，
  1204	         * 再按 5 Hz 航向拍尝试完成切换。 */
  1205	        if (view->heading_switch_pending) {
  1206	            if (view->heading_switch_ready) {
  1207	                view->heading_switch_pending = 0;
  1208	                if (vmap_rot_full(view)) {
  1209	                    view->heading_switch_ready = 0;
  1210	                    if (view->canvas) {
  1211	                        lv_obj_add_flag(view->canvas, LV_OBJ_FLAG_HIDDEN);
  1212	                    }
  1213	                    lv_obj_clear_flag(view->rcanvas, LV_OBJ_FLAG_HIDDEN);
  1214	                } else {
  1215	                    view->heading_switch_pending = 1;
  1216	                }
  1217	            } else {
  1218	                vmap_view_redraw_keep_pan(view);
  1219	            }
  1220	        } else if (vmap_rot_full(view)) {
  1221	            if (view->canvas) {
  1222	                lv_obj_add_flag(view->canvas, LV_OBJ_FLAG_HIDDEN);
  1223	            }
  1224	            lv_obj_clear_flag(view->rcanvas, LV_OBJ_FLAG_HIDDEN);
  1225	        }
  1226	        if (view->canvas) {
  1227	            lv_obj_invalidate(view->canvas);
  1228	        }
  1229	        return;
  1230	    }
  1231	
  1232	    angle = (view->want_rot10 != view->rot10);
  1233	    if (!angle && !view->rot_pending) {
  1234	        return;
  1235	    }
  1236	    if (view->pump_phase != 0u || view->rcanvas == NULL
  1237	        || view->render_rev == 0u
  1238	        || lv_obj_has_flag(view->rcanvas, LV_OBJ_FLAG_HIDDEN)) {
  1239	        return;                 /* 帧在飞（帧末会烘）或还没显示/还没有首帧 */
  1240	    }
  1241	    if (view->last_bake_ms != 0u
  1242	        && lv_tick_elaps(view->last_bake_ms) < VMAP_ROT_BAKE_MIN_MS) {
  1243	        return;                 /* 限频窗口未到：下一拍再来 */
  1244	    }
  1245	    /*
  1246	     * 待应用角度与"帧外增量"合并到**同一次**重烘：否则先用旧角度烘一次增量会刷新
  1247	     * `last_bake_ms`，把角度请求一直挡在窗口外（持续记录时地图永远保持旧朝向）。
  1248	     * 角度**成功烘完才提交**：EPIC 旋转失败时保留 want_rot10，下一拍自动重试，
  1249	     * 不会把请求悄悄丢掉（否则静止时再没有别的东西会触发重烘）。
  1250	     */
  1251	    {
  1252	        const int32_t prev_rot10 = view->rot10;
  1253	
  1254	        /* 探针放在限频检查**之后**：这里才是真的要烘一次（之前的位置会把被窗口挡掉
  1255	         * 的重试也记成一次触发）。 */
  1256	        vmap_rot_why(angle ? 'A' : 'N');
  1257	        view->rot10 = view->want_rot10;
  1258	        if (!vmap_rot_full(view)) {
  1259	            /* 失败记账在 `vmap_rot_full()` 里统一做（见那里的注释）。 */
  1260	            view->rot10 = prev_rot10;
  1261	        }
  1262	    }
  1263	}
  1264	
  1265	/**
  1266	 * @brief 跟车：R 里的内容该位移 (-R(θ)·Δpan)；余量够只挪对象，不够重烘。
  1267	 */
  1268	static void vmap_rot_track(vmap_view_t * view)
  1269	{
  1270	    const double th = (double)view->r_rot10 * 0.1 * M_PI / 180.0;
  1271	    const double c = cos(th);
  1272	    const double s = sin(th);
  1273	    const double dpx = view->pan_dx - view->r_pan_x;
  1274	    const double dpy = view->pan_dy - view->r_pan_y;
  1275	    const int32_t sx = (int32_t)lround(-(c * dpx - s * dpy));
  1276	    const int32_t sy = (int32_t)lround(-(s * dpx + c * dpy));
  1277	    const int32_t lim = view->r_margin - VMAP_ROT_TRACK_GUARD;
  1278	
  1279	    /*
  1280	     * R 可能被写坏（上次整幅超时）：冻结平移，等一次成功重烘把 R 整体重写。
  1281	     * 否则这次位移是按"上一次成功的 r_pan"算的，而 R 里已有一段按新 pan 写入的像素。
  1282	     */
  1283	    if (view->rot_broken) {
  1284	        return;
  1285	    }
  1286	
  1287	    if (view->rot10 != view->r_rot10
  1288	        || abs((int)sx) > lim || abs((int)sy) > lim) {
  1289	        vmap_rot_why('T');
  1290	        vmap_rot_full(view);    /* 角度变了、或余量用完了；失败记账在它内部 */
  1291	        return;
  1292	    }
  1293	
  1294	    vmap_rot_place(view, sx, sy);
  1295	}
  1296	
  1297	static void vmap_view_apply_canvas_pos(vmap_view_t * view, double dx, double dy)
  1298	{
  1299	    lv_coord_t px;
  1300	    lv_coord_t py;
  1301	
  1302	    if (!view || !view->canvas) {
  1303	        return;
  1304	    }
  1305	
  1306	    /* 请求量原样记账（浮点），只有上屏这一步取整 —— 亚像素余量的唯一去处。 */
  1307	    view->pan_rx = dx;
  1308	    view->pan_ry = dy;
  1309	    px = (lv_coord_t)lround(dx);
  1310	    py = (lv_coord_t)lround(dy);
  1311	
  1312	    if (px == view->last_pan_px && py == view->last_pan_py) {
  1313	        return;
  1314	    }
  1315	
  1316	    /*
  1317	     * Moving a canvas invalidates the complete visible map. Coalesce sub-pixel
  1318	     * GNSS movement; the centered arrow still updates normally.
  1319	     */
  1320	    if (view->last_pan_px != INT32_MIN && view->last_pan_py != INT32_MIN
  1321	        && abs((int)px - view->last_pan_px) < VMAP_PAN_MIN_STEP_PX
  1322	        && abs((int)py - view->last_pan_py) < VMAP_PAN_MIN_STEP_PX) {
  1323	        return;
  1324	    }
  1325	
  1326	    view->pan_dx = (double)px;
  1327	    view->pan_dy = (double)py;
  1328	    view->last_pan_px = px;
  1329	    view->last_pan_py = py;
  1330	    view->map_rev++;
  1331	    vmap_label_collector_set_focus(&view->label_col,
  1332	        view->w / 2 + px, view->h / 2 + py);
  1333	#if defined(CONFIG_MYVENDOR_BICYCLE_INVAL_PROBE) && CONFIG_MYVENDOR_BICYCLE_INVAL_PROBE
  1334	    bicycle_inval_probe_tag("vmap_pan");
  1335	#endif
  1336	    /* lv_obj_set_pos already invalidates old + new areas; do not inval again. */
  1337	    /* y_bias 只加在屏幕位置上：pan_dy 与投影原点都不动，于是偏置与跟车/rebase
  1338	     * 的数学完全解耦（偏置变化既不触发重算，也不改变 rebase 时机）。 */
  1339	    if (!view->heading_up || view->heading_switch_pending
  1340	        || !lv_obj_has_flag(view->canvas, LV_OBJ_FLAG_HIDDEN)) {
  1341	        lv_obj_set_pos(view->canvas,
  1342	            (lv_coord_t)(-view->margin - px),
  1343	            (lv_coord_t)(-view->margin - py + view->y_bias));
  1344	        return;
  1345	    }
  1346	
  1347	    /*
  1348	     * 航向朝上：不再让 LVGL 旋转画布（那样每次平移都要重跑一次任意角 transform，
  1349	     * 实测 60 ms/次）。改成维护一块**屏幕对齐的旋转缓冲 R**：只有角度变化或
  1350	     * 余量用完才重烘，平地跟车只移动 R 的对象（见 vmap_rot_track）。
  1351	     */
  1352	    vmap_rot_track(view);
  1353	}
  1354	
  1355	/**
  1356	 * @brief 航向朝上：地图跟随骑行方向旋转（箭头恒指上）。
  1357	 */
  1358	void vmap_view_set_heading_up(vmap_view_t * view, bool enable)
  1359	{
  1360	    if (!view || view->heading_up == enable) {
  1361	        return;
  1362	    }
  1363	
  1364	    if (enable && (view->rcanvas == NULL || view->rbuf == NULL)) {
  1365	        syslog(LOG_WARNING,
  1366	            "[map] heading-up refused: rotated buffer unavailable\n");
  1367	        return;
  1368	    }
  1369	
  1370	    view->heading_up = enable;
  1371	    view->heading_valid = false;
  1372	    view->rot10 = 0;
  1373	    view->want_rot10 = 0;
  1374	    view->r_rot10 = -1;         /* 强制下一次 track 重烘 */
  1375	    view->rot_pending = false;  /* 切换时会立刻重烘，旧的记账作废 */
  1376	
  1377	    if (enable) {
  1378	        if (view->render_rev != 0u) {
  1379	            /* 先保持正北画布 C 可见，等整幅重铺出干净底图再切 R：
  1380	             * 旧路名不会跟着转进 R，也不会和正立标签形成双影。MTP 期间
  1381	             * redraw_keep_pan 会推迟，等 MTP 结束后的帧再补。 */
  1382	            int32_t i;
  1383	
  1384	            view->heading_switch_pending = 1;
  1385	            view->heading_switch_ready = 0;
  1386	            if (view->rcanvas) {
  1387	                lv_obj_add_flag(view->rcanvas, LV_OBJ_FLAG_HIDDEN);
  1388	            }
  1389	            if (view->canvas) {
  1390	                lv_obj_clear_flag(view->canvas, LV_OBJ_FLAG_HIDDEN);
  1391	            }
  1392	            for (i = 0; i < VMAP_ROT_LABEL_MAX; i++) {
  1393	                if (view->rot_label[i] != NULL) {
  1394	                    lv_obj_add_flag(view->rot_label[i], LV_OBJ_FLAG_HIDDEN);
  1395	                }
  1396	            }
  1397	            view->rot_label_n = 0;
  1398	            vmap_view_redraw_keep_pan(view);
  1399	        } else {
  1400	            /* 首帧：C 还没有内容，直接显示 R；首帧烘完自动补齐。 */
  1401	            if (view->rcanvas) {
  1402	                lv_obj_clear_flag(view->rcanvas, LV_OBJ_FLAG_HIDDEN);
  1403	            }
  1404	            if (view->canvas) {
  1405	                lv_obj_add_flag(view->canvas, LV_OBJ_FLAG_HIDDEN);
  1406	            }
  1407	        }
  1408	    } else {
  1409	        view->heading_switch_pending = 0;
  1410	        view->heading_switch_ready = 0;
  1411	        if (view->rcanvas) {
  1412	            lv_obj_add_flag(view->rcanvas, LV_OBJ_FLAG_HIDDEN);
  1413	        }
  1414	        if (view->canvas) {
  1415	            lv_obj_clear_flag(view->canvas, LV_OBJ_FLAG_HIDDEN);
  1416	        }
  1417	        /* 正立路名只在航向朝上时用；退回正北后由烘焙路径接管。 */
  1418	        {
  1419	            int32_t i;
  1420	
  1421	            for (i = 0; i < VMAP_ROT_LABEL_MAX; i++) {
  1422	                if (view->rot_label[i] != NULL) {
  1423	                    lv_obj_add_flag(view->rot_label[i], LV_OBJ_FLAG_HIDDEN);
  1424	                }
  1425	            }
  1426	            view->rot_label_n = 0;
  1427	        }
  1428	    }
  1429	
  1430	    /* 位置公式与标签开关都变了：按新公式重摆，再整幅重来一帧。 */
  1431	    view->last_pan_px = INT32_MIN;
  1432	    view->last_pan_py = INT32_MIN;
  1433	    vmap_view_apply_canvas_pos(view, view->pan_dx, view->pan_dy);
  1434	    syslog(LOG_NOTICE, "[map] heading-up %s\n", enable ? "on" : "off");
  1435	
  1436	    /* 首帧之前不要提前开帧（开机还没进过地图时由页面层控制）。 */
  1437	    if (!enable && view->render_rev != 0u) {
  1438	        vmap_view_render(view);
  1439	    }
  1440	}
