  1769	/**
  1770	 * @brief 取出当前 RGB565 画布描述。
  1771	 */
  1772	bool vmap_view_get_canvas(const vmap_view_t * view, vmap_canvas_t * canvas)
  1773	{
  1774	    if (!view || !canvas || !view->cbuf) {
  1775	        return false;
  1776	    }
  1777	
  1778	    canvas->buf = (uint16_t *)view->cbuf;
  1779	    canvas->w = view->w;
